import { servicenowCssAssetPlugin } from "../../src/vite/css-asset";

type PluginRecord = Record<string, any>;

const simulateMode = (plugin: PluginRecord, command: "serve" | "build") => {
  plugin.configResolved({ command });
};

const makeChunk = (
  fileName: string,
  opts: {
    isEntry?: boolean;
    importedCss?: string[];
    code?: string;
    moduleIds?: string[];
  } = {},
) => ({
  type: "chunk" as const,
  fileName,
  isEntry: opts.isEntry ?? false,
  code: opts.code ?? "",
  moduleIds: opts.moduleIds ?? [],
  viteMetadata: {
    importedCss: new Set(opts.importedCss ?? []),
    importedCssUrls: undefined as Map<string, string> | undefined,
  },
});

const applyConfig = (plugin: PluginRecord, config?: any) => {
  const c = config ?? {};
  plugin.config(c, {} as any);
  return c;
};

describe("servicenowCssAssetPlugin", () => {
  describe("config (renderBuiltUrl)", () => {
    test("rewrites CSS paths to absolute uxta URLs in JS", () => {
      const registerExplicitId = jest.fn().mockReturnValue("abc123");
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId,
      }) as PluginRecord;
      const config = applyConfig(plugin);
      const result = config.experimental.renderBuiltUrl("style.css", {
        hostType: "js",
      });
      expect(result).toBe("/uxta/abc123.assetx");
      expect(registerExplicitId).toHaveBeenCalledWith(
        "sys_ux_theme_asset",
        "style.css",
      );
    });

    test("caches registerExplicitId calls for same CSS file", () => {
      const registerExplicitId = jest.fn().mockReturnValue("abc123");
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId,
      }) as PluginRecord;
      const config = applyConfig(plugin);
      const render = config.experimental.renderBuiltUrl;
      render("style.css", { hostType: "js" });
      render("style.css", { hostType: "js" });
      expect(registerExplicitId).toHaveBeenCalledTimes(1);
    });

    test("returns relative for non-CSS assets", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      const config = applyConfig(plugin);
      const result = config.experimental.renderBuiltUrl("logo.svg", {
        hostType: "js",
      });
      expect(result).toEqual({ relative: true });
    });

    test("returns relative for CSS in HTML", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      const config = applyConfig(plugin);
      const result = config.experimental.renderBuiltUrl("style.css", {
        hostType: "html",
      });
      expect(result).toEqual({ relative: true });
    });

    test("chains with existing renderBuiltUrl", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      const existing = jest.fn().mockReturnValue("/custom/path");
      const config = applyConfig(plugin, {
        experimental: { renderBuiltUrl: existing },
      });
      const result = config.experimental.renderBuiltUrl("logo.svg", {
        hostType: "js",
      });
      expect(existing).toHaveBeenCalledWith("logo.svg", {
        hostType: "js",
      });
      expect(result).toBe("/custom/path");
    });
  });

  describe("configResolved", () => {
    test("throws when build mode and no registerExplicitId", () => {
      const plugin = servicenowCssAssetPlugin() as PluginRecord;
      expect(() => simulateMode(plugin, "build")).toThrow(
        "registerExplicitId is required for build mode",
      );
    });

    test("does not throw in serve mode without registerExplicitId", () => {
      const plugin = servicenowCssAssetPlugin() as PluginRecord;
      expect(() => simulateMode(plugin, "serve")).not.toThrow();
    });

    test("does not throw in build mode with registerExplicitId", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      expect(() => simulateMode(plugin, "build")).not.toThrow();
    });
  });

  describe("renderChunk (preload patch)", () => {
    const PRELOAD_HELPER_ID = "\0vite/preload-helper.js";
    const PRELOAD_CODE =
      'let isCss=dep.endsWith(".css");if(isCss){link.rel="stylesheet"}';

    test("patches CSS detection to include .assetx", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      simulateMode(plugin, "build");

      const chunk = makeChunk("main.jsdbx", {
        isEntry: true,
        moduleIds: [PRELOAD_HELPER_ID],
        code: PRELOAD_CODE,
      });
      const result = plugin.renderChunk(chunk.code, chunk);
      expect(result.code).toContain(
        'dep.endsWith(".css")||dep.endsWith(".assetx")',
      );
    });

    test("returns a sourcemap", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      simulateMode(plugin, "build");

      const chunk = makeChunk("main.jsdbx", {
        isEntry: true,
        moduleIds: [PRELOAD_HELPER_ID],
        code: PRELOAD_CODE,
      });
      const result = plugin.renderChunk(chunk.code, chunk);
      expect(result.map).toBeDefined();
      expect(result.map.version).toBe(3);
    });

    test("skips chunks without preload helper", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      simulateMode(plugin, "build");

      const chunk = makeChunk("main.jsdbx", {
        isEntry: true,
        moduleIds: ["src/main.ts"],
        code: PRELOAD_CODE,
      });
      const result = plugin.renderChunk(chunk.code, chunk);
      expect(result).toBeNull();
    });

    test("skips when target string not found", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      simulateMode(plugin, "build");

      const chunk = makeChunk("main.jsdbx", {
        isEntry: true,
        moduleIds: [PRELOAD_HELPER_ID],
        code: "console.log('no preload here')",
      });
      const result = plugin.renderChunk(chunk.code, chunk);
      expect(result).toBeNull();
    });

    test("skips in serve mode", () => {
      const plugin = servicenowCssAssetPlugin() as PluginRecord;
      simulateMode(plugin, "serve");

      const chunk = makeChunk("main.jsdbx", {
        isEntry: true,
        moduleIds: [PRELOAD_HELPER_ID],
        code: PRELOAD_CODE,
      });
      const result = plugin.renderChunk(chunk.code, chunk);
      expect(result).toBeNull();
    });
  });

  describe("generateBundle (importedCssUrls)", () => {
    test("populates importedCssUrls on chunks with CSS", () => {
      const registerExplicitId = jest.fn().mockReturnValue("abc123");
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId,
      }) as PluginRecord;
      simulateMode(plugin, "build");

      const chunk = makeChunk("main.jsdbx", {
        isEntry: true,
        importedCss: ["main.css"],
      });
      const bundle = { "main.jsdbx": chunk };

      plugin.generateBundle({}, bundle);
      expect(chunk.viteMetadata.importedCssUrls).toEqual(
        new Map([["main.css", "/uxta/abc123.assetx"]]),
      );
    });

    test("skips chunks without CSS", () => {
      const plugin = servicenowCssAssetPlugin({
        registerExplicitId: () => "id",
      }) as PluginRecord;
      simulateMode(plugin, "build");

      const chunk = makeChunk("main.jsdbx", {
        isEntry: true,
        importedCss: [],
      });
      const bundle = { "main.jsdbx": chunk };

      plugin.generateBundle({}, bundle);
      expect(chunk.viteMetadata.importedCssUrls).toBeUndefined();
    });

    test("skips in serve mode", () => {
      const plugin = servicenowCssAssetPlugin() as PluginRecord;
      simulateMode(plugin, "serve");

      const chunk = makeChunk("main.jsdbx", {
        isEntry: true,
        importedCss: ["main.css"],
      });
      const bundle = { "main.jsdbx": chunk };

      plugin.generateBundle({}, bundle);
      expect(chunk.viteMetadata.importedCssUrls).toBeUndefined();
    });
  });
});
